            //      spotTresholdPrice.
            //
            // Pokud jsou všechny podmínky splněny, nastaví se záporný Grid Point,
            // čímž se povolí export energie z baterie do distribuční sítě.
            //
            // Cílem funkce je využít večerní cenovou špičku k prodeji energie,
            // přičemž je zachována minimální požadovaná energetická rezerva baterie.
            // ============================================================================
            if (nEveningPeakBatterySales) { // Povolena funkce večerního prodeje
                if (afternoonPeak1.length > 0) { // Existuje definované večerní špičkové období
                    // Výpočet začátku a konce večerní špičky
                    const peakTimeStart = new Date(oDate_CZ.getFullYear(), oDate_CZ.getMonth(), oDate_CZ.getDate(), afternoonPeak1[0], 0, 0, 0);
