                                if (currentPrice >= spotTresholdPrice) {// Spotová cena dosáhla požadovaného limitu
                                    nSet_Grid_Point = EnsureNegativeValue(nMAX_Grid_Point);  //Povolení exportu energie z baterie do sítě

