                    const peakTimeEnd = new Date(oDate_CZ.getFullYear(), oDate_CZ.getMonth(), oDate_CZ.getDate(), morningPeak1[morningPeak1.length - 1] + 1, 0, 0, 0);                      

                    if (oDate_CZ >= peakTimeStart && oDate_CZ < peakTimeEnd) {   

