                            nSet_Grid_Point = EnsurePositiveValue(nMAX_Grid_Point);                                                                                   
                        }                     
                    }                                     
                }  
            }
        }

        // ============================================================================
        // LINEA API R2.1 :: Decision / Telemetry Snapshot
        // READ ONLY
        //
        //
        // R2.1:
        // - oprava nControl_Mode_ESS_AC_Grid: není lokální proměnná AC LOAD,
        //   proto se čte read-only přes getConfigProperty()/global.get()
        // - ostatní provozní hodnoty jsou použity pouze z proměnných, které jsou
        //   v aktuálním AC LOAD skutečně deklarované
        // - baterie je normalizovaná na W / A / V / %
        // - časy jsou HH:MM + původní ms
        // - všechny přepínače jsou JSON boolean
        // ============================================================================

        function lineaToHHMM(v) {
            if (v === null || v === undefined || v === 0) return "00:00";

            if (typeof v === "number") {
                if (v > 86400000) {
                    const d = new Date(v);
                    return String(d.getHours()).padStart(2, "0") + ":" +
                        String(d.getMinutes()).padStart(2, "0");
                }

                const h = Math.floor(v / 3600000);
                const m = Math.floor((v % 3600000) / 60000);

                return String(h).padStart(2, "0") + ":" +
                    String(m).padStart(2, "0");
            }

            const match = /(\d{1,2}):(\d{2})/.exec(String(v));

            return match
                ? match[1].padStart(2, "0") + ":" + match[2]
                : "00:00";
        }

        function lineaBool(v) {
            return !!v;
        }

        // ---------------------------------------------------------------------------
        // Jediná hodnota snapshotu, která NENÍ lokální proměnná AC LOAD.
        // Čteme ji přes stejný centrální config getter, který používá LINEA.
        // Fallback na global.get() zachovává kompatibilitu se zrcadlenou hodnotou.
        // ---------------------------------------------------------------------------
        const lineaGetConfig = global.get("getConfigProperty");

        const lineaControlModeEssAcGrid = lineaGetConfig
            ? !!lineaGetConfig("nControl_Mode_ESS_AC_Grid")
            : !!global.get("nControl_Mode_ESS_AC_Grid");

        // ---------------------------------------------------------------------------
        // Normalizace baterie.
        // AC LOAD již obsahuje nConvertSignetUnsignet.
        // Current, Voltage a BatteryLife SOC používají scale factor 10.
        // ---------------------------------------------------------------------------
        const lineaBatteryPowerW =
            nConvertSignetUnsignet(nBattery_Power);

        const lineaBatteryCurrentA =
            nConvertSignetUnsignet(nBattery_Current) / 10;

        const lineaBatteryVoltageV =
            nConvertSignetUnsignet(nBattery_Voltage) / 10;

        const lineaBatteryLifeSocLimitPct =
            (Number(nESS_BatteryLife_SoC_limit) || 0) / 10;

        // Důvod rozhodnutí zatím API neodhaduje.
        // Později bude reasonCode nastaven přímo v rozhodovacích větvích AC LOAD.
        const lineaDecisionReason = {
            code: "UNCLASSIFIED",
            text: null
        };

        const lineaDecisionState = {
            timestamp: new Date().toISOString(),

            telemetry: {
                pvPowerW: Number(pvPower) || 0,
                housePowerW: Number(totalACLoad) || 0,
                gridPowerW: Number(totalGRID) || 0,

                phases: {
                    house: {
                        l1PowerW: Number(phase1) || 0,
                        l2PowerW: Number(phase2) || 0,
                        l3PowerW: Number(phase3) || 0
                    },

                    grid: {
                        l1PowerW: Number(grid1) || 0,
                        l2PowerW: Number(grid2) || 0,
                        l3PowerW: Number(grid3) || 0
                    }
                },

                battery: {
                    socPct: Number(nBattery_State_Charge) || 0,
                    powerW: lineaBatteryPowerW,
                    currentA: lineaBatteryCurrentA,
                    voltageV: lineaBatteryVoltageV,
                    batteryLifeSocLimitPct: lineaBatteryLifeSocLimitPct
                }
            },

            ess: {
                decision: {
                    gridPointW: Number(nSet_Grid_Point) || 0,
                    pvSurplusW: Number(nZbytekFV) || 0,
                    predictionActive: lineaBool(bPredikce),
                    exportAllowed: lineaBool(nPretoky),
                    reason: lineaDecisionReason
                },

                switches: {
                    controlModeEssAcGrid: lineaControlModeEssAcGrid,
                    spotGridCharging: lineaBool(switchSpotGridCharging),
                    gridCharging: lineaBool(sGridChargingSwitch),
                    gridConsumption: lineaBool(nGridConsumptionEnable),
                    energyThresholdInjector: lineaBool(nEnergyThresholdInjector),
                    nonBatteryPriority: lineaBool(nNonBatteryPriorityMode),
                    delayCharging: lineaBool(switchDelayCharging),
                    dynamicSocReserve: lineaBool(nDynamicSOC_Reserve),
                    predictionThreshold: lineaBool(nPredictionThreshold),
                    socDeltaBeforeExport: lineaBool(nSOCDeltaBeforeExport_Switch),
                    morningPeakBatterySales: lineaBool(nMorningPeakBatterySales),
                    eveningPeakBatterySales: lineaBool(nEveningPeakBatterySales)
                },

                settings: {
                    balancingReserveW: Number(nBalancingReserve) || 0,
                    setGridValueW: Number(nSetGridValue) || 0,
                    maxGridPointW: Number(nMAX_Grid_Point) || 0,
                    spotThresholdPrice: Number(spotTresholdPrice) || 0,
                    morningSocSalesPct: Number(nMorningSOC_sales) || 0,
                    eveningSocSalesPct: Number(nEveningSOC_sales) || 0,
                    gridChargingSocPct: Number(nGridChargingSOC) || 0,
                    predictionThresholdKWh: Number(sPredictionThresholdKW) || 0,
                    socDeltaBeforeExportPct: Number(nSOCDeltaBeforeExport) || 0,
                    chargingDurationGridH: Number(nCharging_DurationGRID) || 0,
                    acceptablePriceGrid: Number(nAcceptable_Price_GRID) || 0
                },

                time: {
                    delayCharging: {
                        start: lineaToHHMM(tStartBattery),
                        stop: lineaToHHMM(tStopBattery),
                        startMs: Number(tStartBattery) || 0,
                        stopMs: Number(tStopBattery) || 0
                    },

                    morningPeakHours:
                        Array.isArray(morningPeak1) ? morningPeak1 : [],

                    eveningPeakHours:
                        Array.isArray(afternoonPeak1) ? afternoonPeak1 : []
                }
            },

            spot: {
                currentPrice: Number(currentPrice) || 0
            }
        };

        global.set("lineaDecisionState", lineaDecisionState);

        // ============================================================================
        // END LINEA API R2.1 snapshot
        // ============================================================================


        // Nastavit celkový odběr jako novou hodnotu pro nastavení sítě
        msg.payload = { "nSet_Grid_Point": nSet_Grid_Point,
                        "nGET_Grid_Feed_2706": nGET_Grid_Feed_2706,
                        "pvPower": pvPower,
                        "nMAX_Grid_Point": nMAX_Grid_Point,
                        "totalACLoad": totalACLoad,
                        "nZbytekFV": nZbytekFV
                        };

        } else {// nenalezeny globalni funkce
        node.error("Globální funkce nebyly nalezeny. <-- FORM BATTERY CONTROL-- AC LOAD");
    }
    return msg;
} catch (error) {
    node.error("Error in script: " + error.message);
}

// Oprava validnich dat z MBUSu, pokud bude X krat po sobe nula, tak vysledek bude nula, pokud bude nula 1x a min nez trigger, 
// tak se vezme hodnota z globalniho buffru
function fCheckValue(pvPowerReading, readingCount, globalVarName) {
    // Dynamicky vytvoří název čítače na základě globalVarName
    let zeroReadingsCountKey = `${globalVarName}_Count`;

    // Získá dynamicky čítač a počáteční hodnotu výkonu z globálních proměnných
    let zeroReadingsCount = global.get(zeroReadingsCountKey) || 0;
    let pvPower = global.get(globalVarName) ?? 0; // Defaultně nastavíme na 0, pokud není dostupná globální hodnota

    if (pvPowerReading === 0) {
        // Zvýšení čítače, pokud byla přečtena hodnota 0
        zeroReadingsCount += 1;

        if (zeroReadingsCount >= readingCount) {
            // Pokud čítač dosáhne požadovaného počtu, nastavíme pvPower na 0
            pvPower = 0;
            zeroReadingsCount = 0; // Resetování čítače
        }
    } else if (pvPowerReading === null) {
        // Pokud je čtení neplatné, použijeme globální proměnnou
        zeroReadingsCount = 0; // Reset čítače, pokud čtení nebylo 0
    } else {
        // Pokud je čtení platné a nenulové, používáme ho
        pvPower = pvPowerReading;
        zeroReadingsCount = 0; // Reset čítače, pokud čtení nebylo 0
    }

    // Uložení dynamicky generovaného čítače zpět do globální proměnné
    global.set(zeroReadingsCountKey, zeroReadingsCount);
    // Uložení dynamicky generované hodnoty výkonu zpět do globální proměnné
    global.set(globalVarName, pvPower);

    return pvPower;
}

/**
