/**
 * HISTORY · Linea/FVE — správa snapshotů (kompletní zálohy konfigurace)
 * @author  hacesoft · https://github.com/hacesoft/Linea
 * @license GPL-3.0-or-later · (c) hacesoft
 *
 * Snapshot = jeden JSON se sekcemi: config + shellyDevices + daikinConfig.
 * daikin_tokens.json se ZÁMĚRNĚ nezálohuje (živé OAuth tokeny, rotují).
 *
 * Vstupy (msg.topic): histList / histSave / histLoad / histDelete
 * Výstup 1: zpráva pro CONFIG_WIDGET
 * Výstup 2: trigger "load" pro Get Config (jen u histLoad)
 */
const debug = false;

const path_file = (global.get("sValid_Patch") || "") + "/";
const filename  = global.get("filename");
const histDir   = path_file + "config_history/";
const mainCfg   = path_file + filename;

// Názvy vedlejších souborů
const fnShelly  = global.get("filenameShellyDevices") || "ShellyDevices_hacesoft.json";
const fnDaikin  = "daikin_config.json";   // tokens se nezálohují!

const pShelly = path_file + fnShelly;
const pDaikin = path_file + fnDaikin;

function safeName(n) {
    return typeof n === 'string' && /^[\w\-\.]+\.json$/.test(n) && n.indexOf('..') === -1;
}

function readJsonSafe(p) {
    try {
        if (fs.existsSync(p)) return JSON.parse(fs.readFileSync(p, 'utf8'));
    } catch (e) {
        if (debug) node.warn('readJsonSafe ' + p + ': ' + e.message);
    }
    return null;
}

function listSnapshots() {
    if (!fs.existsSync(histDir)) fs.mkdirSync(histDir, { recursive: true });
    return fs.readdirSync(histDir)
        .filter(f => f.endsWith('.json'))
        .map(f => {
            const st = fs.statSync(histDir + f);
            return { name: f, size: st.size, mtime: st.mtimeMs };
        })
        .sort((a, b) => b.mtime - a.mtime);
}

try {
    switch (msg.topic) {

        case 'histList':
            return [{ topic: 'histList', payload: listSnapshots() }, null];

        case 'histSave': {
            const cfg = global.get('config');
            if (!cfg) return [{ topic: 'histError', payload: 'Není co uložit (config je prázdný)' }, null];
            if (!fs.existsSync(histDir)) fs.mkdirSync(histDir, { recursive: true });

            const ts = new Date().toISOString().slice(0, 19).replace('T', '_').replace(/:/g, '-');
            let label = ts;
            if (typeof msg.payload === 'string' && msg.payload.trim()) {
                const cand = msg.payload.trim().replace(/[^\w\-]/g, '_');
                if (cand) label = cand;
            }
            let fname = label + '.json';
            if (fs.existsSync(histDir + fname)) {
                label = label + '_' + ts;
                fname = label + '.json';
            }

            // Kompletní snapshot: config (z paměti) + shelly (z paměti) + daikin (ze souboru)
            const snapshot = {
                sName: label,
                savedAt: ts,
                config: Object.assign({}, cfg, { sName: label }),
                shellyDevices: global.get('shellyDevices')
                            || global.get('defaultShellyDevices') || {},
                daikinConfig: readJsonSafe(pDaikin)   // null když soubor neexistuje
            };
            fs.writeFileSync(histDir + fname, JSON.stringify(snapshot, null, 2));

            if (debug) node.warn('Snapshot: ' + fname);
            return [{ topic: 'histList', payload: listSnapshots(), info: 'Snapshot uložen' }, null];
        }

        case 'histLoad': {
            if (!safeName(msg.payload)) return [{ topic: 'histError', payload: 'Neplatný název souboru' }, null];
            const src = histDir + msg.payload;
            if (!fs.existsSync(src)) return [{ topic: 'histError', payload: 'Soubor neexistuje' }, null];

            const snap = JSON.parse(fs.readFileSync(src, 'utf8'));

            if (snap && snap.config) {
                // NOVÝ formát: rozepsat sekce do pracovních souborů
                fs.writeFileSync(mainCfg, JSON.stringify(snap.config, null, 2));

                if (snap.shellyDevices !== undefined && snap.shellyDevices !== null) {
                    fs.writeFileSync(pShelly, JSON.stringify(snap.shellyDevices, null, 2));
                }
                if (snap.daikinConfig !== undefined && snap.daikinConfig !== null) {
                    fs.writeFileSync(pDaikin, JSON.stringify(snap.daikinConfig, null, 2));
                }
                // daikin_tokens.json se NIKDY nepřepisuje — živé tokeny zůstávají
            } else {
                // STARÝ formát (plochý config bez sekcí): kompatibilita
                fs.copyFileSync(src, mainCfg);
            }

            if (debug) node.warn('Obnoven snapshot: ' + msg.payload);
            return [
                { topic: 'histList', payload: listSnapshots(), info: 'Konfigurace obnovena' },
                { payload: 'load' }
            ];
        }

        case 'histDelete': {
            if (!safeName(msg.payload)) return [{ topic: 'histError', payload: 'Neplatný název souboru' }, null];
            const f = histDir + msg.payload;
            if (fs.existsSync(f)) fs.unlinkSync(f);
            return [{ topic: 'histList', payload: listSnapshots() }, null];
        }
    }
} catch (e) {
    return [{ topic: 'histError', payload: 'Chyba: ' + e.message }, null];
}
return null;

/**
 * Boot_Connect · Linea/FVE — po prvním úspěšném načtení konfigurace spustí TCP connect
 * @author  hacesoft · https://github.com/hacesoft/Linea
 * @license GPL-3.0-or-later · (c) hacesoft
 */
if (flow.get('bootConnected')) return null;                                  // jen jednou po startu ND
if (msg.highlight !== 'green' && msg.highlight !== 'yellow') return null;    // load neprobehl uspesne

flow.set('bootConnected', true);
return { topic: 'connect', payload: 'connect' };

// Cte global StatusIndicator_MODBUS (plni Check Connection) — posle jen pri zmene
const s = global.get("StatusIndicator_MODBUS") || "off";
if (context.get("last") === s) return null;
context.set("last", s);
msg.topic = "tcpStatus";
msg.payload = (s === "on");
return msg;

