//
//*****************************************************************************
// RESET — provede se až po validaci cesty (sValid_Patch)
// Revised: 27-06-2026
//*****************************************************************************
const debug = false;

const MAX_WAIT = 30000;   // max 30 s čekání na cestu (pojistka)
const POLL = 250;         // interval kontroly v ms

// Kontrola, zda je cesta validní
function isPatchValid() {
        const p = global.get("sValid_Patch");
        return (typeof p === "string" && p.length > 0);
}

// Pokud je cesta hned validní, pokračuj rovnou
if (isPatchValid()) {
        msg.payload = { reset: true, description: "Reset dokončen (cesta OK)" };
        node.status({ fill: "green", shape: "dot", text: "RESET — cesta OK" });
        return msg;
}

// Cesta zatím není — čekej a periodicky kontroluj
node.status({ fill: "yellow", shape: "ring", text: "čekám na sValid_Patch…" });

const start = Date.now();
const timer = setInterval(() => {
        if (isPatchValid()) {
                clearInterval(timer);
                node.status({ fill: "green", shape: "dot", text: "RESET — cesta nalezena" });
                node.send({ payload: { reset: true, description: "Reset dokončen (po validaci)" } });
        } else if (Date.now() - start > MAX_WAIT) {
                clearInterval(timer);
                node.status({ fill: "red", shape: "ring", text: "TIMEOUT — cesta nenalezena!" });
                node.warn("RESET: sValid_Patch se nepodařilo získat do " + (MAX_WAIT / 1000) + "s");
                // I tak pošli reset, ať systém nezůstane viset (volitelné — můžeš odebrat)
                node.send({ payload: { reset: true, description: "Reset (TIMEOUT bez validní cesty!)" } });
        }
}, POLL);

return null;   // hned nic neposílej, čeká timer

