// GitHub API – výpis souborů v adresáři release

msg.url =
    "https://api.github.com/repos/hacesoft/Linea/contents/release";

msg.headers = {
    "User-Agent": "Node-RED-Linea-Checker",
    "Accept": "application/vnd.github.v3+json"
};

return msg;

//*****************************************************************************
// LINEA - KONTROLA VERZE FLOW NA GITHUBU
//
// Z názvu souboru se ignoruje veškerý text.
// Rozhodující je pouze datum a čas na konci:
//
//   COKOLIV_30082026_1546.json
//   ALL_flows_30082026_1546.json
//   SELECTION_cokoliv_30082026_1546.zip
//
// Lokální verze:
//   config.flow_version = "30082026_1546"
//*****************************************************************************

const debug = false;

// Lokální verze FLOW je při inicializaci převzata
// z config.flow_version do této globální proměnné.
const localRaw = String(global.get("linea_version_local") || "??");


//-----------------------------------------------------------------------------
// DDMMYYYY_HHMM -> YYYYMMDDHHMM
// Pro snadné číselné porovnání verzí.
//-----------------------------------------------------------------------------
function versionNumber(v) {
    const m = String(v).match(/^(\d{2})(\d{2})(\d{4})_(\d{2})(\d{2})$/);
    if (!m) return null;

    const [, dd, mm, yyyy, hh, min] = m;

    if (
        +dd < 1 || +dd > 31 ||
        +mm < 1 || +mm > 12 ||
        +hh < 0 || +hh > 23 ||
        +min < 0 || +min > 59
    ) {
        return null;
    }

    return Number(`${yyyy}${mm}${dd}${hh}${min}`);
}


//-----------------------------------------------------------------------------
// Z názvu souboru vezme pouze DDMMYYYY_HHMM před .json nebo .zip.
// Veškerý text před verzí je ignorován.
//-----------------------------------------------------------------------------
function versionFromFilename(name) {
    const m = String(name || "").match(
        /(\d{8})_(\d{4})\.(?:json|zip)$/i
    );

    return m ? `${m[1]}_${m[2]}` : null;
}


//-----------------------------------------------------------------------------
// Lokální verze FLOW
//-----------------------------------------------------------------------------
const localNumber = versionNumber(localRaw);

if (localNumber === null) {
    node.warn(`Neplatná config.flow_version: ${localRaw}`);
    return null;
}


//-----------------------------------------------------------------------------
// GitHub musí vrátit seznam souborů.
//-----------------------------------------------------------------------------
if (!Array.isArray(msg.payload)) {
    node.warn("GitHub API nevrátilo seznam souborů.");
    return null;
}


//-----------------------------------------------------------------------------
// Najdi nejnovější soubor podle data a času v názvu.
//-----------------------------------------------------------------------------
let latest = null;

for (const file of msg.payload) {
    if (!file?.name) continue;

    const raw = versionFromFilename(file.name);
    if (!raw) continue;

    const number = versionNumber(raw);
    if (number === null) continue;

    if (!latest || number > latest.number) {
        latest = {
            raw,
            number,
            filename: file.name
        };
    }
}


//-----------------------------------------------------------------------------
// Žádný soubor s DDMMYYYY_HHMM nebyl nalezen.
//-----------------------------------------------------------------------------
if (!latest) {
    node.warn("V release/ nebyl nalezen soubor s verzí DDMMYYYY_HHMM.");
    return null;
}


//-----------------------------------------------------------------------------
// Porovnání lokální a GitHub verze.
//-----------------------------------------------------------------------------
const updateAvailable = latest.number > localNumber;


//-----------------------------------------------------------------------------
// Globální hodnoty pro Dashboard.
//-----------------------------------------------------------------------------
global.set("linea_version_local", localRaw);
global.set("linea_version_remote", latest.raw);
global.set("linea_version_update_available", updateAvailable);
