const debug = false;

// Souřadnice - primárně z flow (GPS flow), fallback na global
const lat = flow.get("Latitude") !== undefined ? flow.get("Latitude") : global.get("Latitude");
const lng = flow.get("Longitude") !== undefined ? flow.get("Longitude") : global.get("Longitude");

if (lat === undefined || lat === null || lng === undefined || lng === null) {
    if (debug) node.warn("Open-Meteo: GPS souřadnice nejsou k dispozici, dotaz přeskočen");
    node.status({ fill: "yellow", shape: "ring", text: "čekám na GPS souřadnice" });
    return null;
}

msg.url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}` +
    `&daily=weather_code,precipitation_probability_max,sunshine_duration,shortwave_radiation_sum` +
    `&timezone=auto&forecast_days=2`;
msg.method = "GET";
msg.headers = { "Content-Type": "application/json" };

