//*****************************************************************************
//
// File Name        : Weather Processor
// Title            : Zpracování odpovědi z Open-Meteo API
// Author           : http://www.prochazka.zde.cz
// Created          : 05-07-2026
// Revised          : 05-07-2026
// Version          : 1.0
// Target Platform  : Node-RED
//
// OPEN-METEO API VYSVĚTLENÍ:
// ==========================
// weather_code:                  WMO kód počasí (0=jasno, 3=zataženo, 61-67=déšť...)
// precipitation_probability_max: Max. pravděpodobnost srážek za den (%)
// sunshine_duration:             Doba slunečního svitu za den (sekundy)
// shortwave_radiation_sum:       Denní suma slunečního záření (MJ/m²)
//                                -> nejlepší ukazatel pro predikci výroby FVE!
//
// Trend výroby = porovnání shortwave_radiation_sum zítra vs. dnes.
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2026 hacesoft.
//
//*****************************************************************************
const debug = false;

// Kontrola úspěšné odpovědi
if (msg.statusCode !== 200 || !msg.payload || !msg.payload.daily) {
    if (debug) node.warn("Open-Meteo chyba - statusCode: " + msg.statusCode);
    node.status({ fill: "red", shape: "ring", text: "chyba API: " + msg.statusCode });
    return null;
}

try {
    const d = msg.payload.daily;

    // Trend výroby: porovnání sumy záření zítra vs. dnes
    const radToday = d.shortwave_radiation_sum[0];    // MJ/m²
    const radTomorrow = d.shortwave_radiation_sum[1];
    let trend = "→ stejné";
    if (radToday > 0) {
        const diff = ((radTomorrow - radToday) / radToday) * 100;
        if (diff > 10)       trend = `↗ zítra lepší (+${diff.toFixed(0)} %)`;
        else if (diff < -10) trend = `↘ zítra horší (${diff.toFixed(0)} %)`;
    }

    const weatherData = {
        today: wmoText(d.weather_code[0]),
        tomorrow: wmoText(d.weather_code[1]),
        rainProbToday: d.precipitation_probability_max[0],
        rainProbTomorrow: d.precipitation_probability_max[1],
        sunshineHours: (d.sunshine_duration[0] / 3600).toFixed(1),
        radToday: radToday,
        radTomorrow: radTomorrow,
        trend: trend,
        updated: new Date().toISOString()
    };

    // Uložení do global proměnných pro RealData_Build
    global.set("weatherData", weatherData);

    msg.payload = weatherData;
    node.status({ fill: "green", shape: "dot", text: `${weatherData.today} · ${trend}` });

    if (debug) {
        node.warn("Počasí dnes: " + weatherData.today);
        node.warn("Trend: " + trend);
    }

} catch (error) {
    node.error("Chyba při zpracování Open-Meteo dat: " + error.message);
    node.status({ fill: "red", shape: "ring", text: "chyba zpracování" });
    msg.payload = {
        success: false,
        error: "Chyba při zpracování dat",
        message: error.message
    };
}

return msg;

// WMO weather kódy -> český popis
function wmoText(code) {
    if (code === 0) return "Jasno ☀️";
    if (code === 1) return "Skoro jasno 🌤️";
    if (code === 2) return "Polojasno ⛅";
    if (code === 3) return "Zataženo ☁️";
    if (code === 45 || code === 48) return "Mlha 🌫️";
    if (code >= 51 && code <= 57) return "Mrholení 🌦️";
    if (code >= 61 && code <= 67) return "Déšť 🌧️";
    if (code >= 71 && code <= 77) return "Sněžení 🌨️";
    if (code >= 80 && code <= 82) return "Přeháňky 🌦️";
    if (code >= 95) return "Bouřky ⛈️";
    return "—";
}

