// Target Platform  : Node-RED
//
// Poloha se hledá postupně:
// 1) top-level pole latitude/longitude na záznamu instalace
// 2) extended atributy (code "lt"/"lg" nebo description Latitude/Longitude)
// 3) fallback: config -> location: { latitude, longitude }
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2026 hacesoft.
//
//*****************************************************************************
const debug = false;   // po odladění přepni na false

const fGetConfigProperty = global.get('getConfigProperty');
const nVRM_site_id = fGetConfigProperty("nVRM_site_id");

let lat = null;
let lng = null;
let source = null;

// ---------- 1) + 2) VRM odpověď ----------
if (msg.statusCode === 200 && msg.payload && msg.payload.records) {

    // idSite v odpovědi může být číslo i řetězec -> porovnáváme volně (==)
    const site = msg.payload.records.find(r => r.idSite == nVRM_site_id) || msg.payload.records[0];

    if (site) {
        // 1) top-level pole
        if (site.latitude !== undefined && site.latitude !== null &&
            site.longitude !== undefined && site.longitude !== null) {
            lat = parseFloat(site.latitude);
            lng = parseFloat(site.longitude);
            source = "VRM (top-level)";
        }

        // 2) extended atributy
        if ((lat === null || isNaN(lat)) && Array.isArray(site.extended)) {
            for (const attr of site.extended) {
                const code = (attr.code || "").toLowerCase();
                const desc = (attr.description || "").toLowerCase();
                const val = attr.rawValue !== undefined ? attr.rawValue : attr.formattedValue;

                if (code === "lt" || desc === "latitude") {
                    lat = parseFloat(val);
                }
                if (code === "lg" || desc === "longitude") {
                    lng = parseFloat(val);
                }
            }
            if (lat !== null && lng !== null && !isNaN(lat) && !isNaN(lng)) {
                source = "VRM (extended)";
            }
        }

        // Diagnostika - co VRM vlastně poslalo
        if (debug && source === null) {
            node.warn("Location: top-level klíče záznamu: " + Object.keys(site).join(", "));
            if (Array.isArray(site.extended)) {
                node.warn("Location: extended codes: " +
                    site.extended.map(a => a.code + " (" + a.description + ")").join(", "));
            } else {
                node.warn("Location: záznam nemá pole extended");
            }
        }
    }
} else {
    if (debug) node.warn("Location: VRM API chyba - statusCode: " + msg.statusCode);
}

// ---------- 3) Fallback: pevné nastavení z configu ----------
if (lat === null || lng === null || isNaN(lat) || isNaN(lng)) {
    const oLocation = fGetConfigProperty("location") || {};
    if (oLocation.latitude !== undefined && oLocation.longitude !== undefined) {
        lat = parseFloat(oLocation.latitude);
        lng = parseFloat(oLocation.longitude);
        source = "config (pevné nastavení)";
    }
}

// ---------- Výsledek ----------
if (lat === null || lng === null || isNaN(lat) || isNaN(lng)) {
    node.status({ fill: "red", shape: "ring", text: "poloha nenalezena (VRM ani config)" });
    return null;
}

global.set("Latitude", lat);
global.set("Longitude", lng);

node.status({ fill: "green", shape: "dot", text: `${lat.toFixed(4)}, ${lng.toFixed(4)} · ${source}` });

if (debug) node.warn(`Poloha: ${lat}, ${lng} (zdroj: ${source})`);

msg.payload = { latitude: lat, longitude: lng, source: source };
return msg;

//*****************************************************************************
//
// File Name        : PV Modbus Request
// Title            : Generování Modbus dotazů pro SmartSolar MPPT (auto z VRM)
// Author           : http://www.prochazka.zde.cz
// Created          : 05-07-2026
// Revised          : 05-07-2026
// Version          : 2.0
// Target Platform  : Node-RED
//
// Unit ID = device instance z VRM (platí pro instance <= 247).
// Pro instance > 247 platí interní mapovací tabulka Venus OS,
// kterou VRM API neposkytuje -> doplň ručně do OVERRIDE.
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2026 hacesoft.
//
//*****************************************************************************

// ===== OVERRIDE - unit ID pro instance > 247 (instance: unitId) =====
// !!! UPRAV PODLE REMOTE CONSOLE !!!
// Settings -> Services -> Modbus TCP -> Available services
const OVERRIDE = {
    278: 224,   // MPPT WEST - PŘEPIŠ na skutečné unit ID!
    279: 226    // MPPT VJ   - PŘEPIŠ na skutečné unit ID!
};
// =====================================================================

const names = global.get("vrmSolarNames") || {};
const instances = Object.keys(names);

if (instances.length === 0) {
    node.status({ fill: "yellow", shape: "ring", text: "čekám na vrmSolarNames (VRM flow)" });
    return null;
}

const out = [];
const problems = [];

for (const instStr of instances) {
    const inst = parseInt(instStr);
    let unitId = inst;

    if (inst > 247) {
        if (OVERRIDE[inst] !== undefined) {
            unitId = OVERRIDE[inst];
        } else {
            problems.push(inst);
            continue;
        }
    }

    out.push({
        pvMeta: { unitId: unitId, name: names[instStr], count: instances.length - problems.length },
        payload: {
            value: '',
            fc: 3,
            unitid: unitId,
            address: 771,
            quantity: 16
        }
    });
}

if (problems.length > 0) {
    node.status({ fill: "yellow", shape: "dot", text: "instance > 247, doplň OVERRIDE: " + problems.join(", ") });
} else {
    node.status({ fill: "green", shape: "dot", text: `${out.length} MPPT dle VRM` });
}

return [out];

//*****************************************************************************
//
// File Name        : PV Modbus Processor
// Title            : Zpracování registrů 771-786 ze SmartSolar MPPT
// Author           : http://www.prochazka.zde.cz
// Created          : 05-07-2026
// Revised          : 05-07-2026
// Version          : 1.0
// Target Platform  : Node-RED
//
// REGISTRY (offset od 771):
// [0]  771 Battery voltage (výstup MPPT)  uint16  x100  V
// [1]  772 Battery current (výstup MPPT)  int16   x10   A
// [5]  776 PV voltage (string)            uint16  x100  V
// [13] 784 Yield today                    uint16  x10   kWh
//
// Výkon stringu = battV * battI, PV proud = výkon / PV napětí
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2026 hacesoft.
//
//*****************************************************************************
const debug = false;

if (!msg.pvMeta) return null;

const vals = Array.isArray(msg.payload) ? msg.payload : (msg.payload && msg.payload.data);
if (!vals || vals.length < 16) {
    node.status({ fill: "red", shape: "ring", text: "neplatná data unit " + msg.pvMeta.unitId });
    return null;
}

function toInt16(v) { return v > 32767 ? v - 65536 : v; }

const battV = vals[0] / 100;
const battI = toInt16(vals[1]) / 10;
const pvV = vals[5] / 100;
const yieldToday = vals[13] / 10;

const power = Math.round(battV * battI);
const pvI = pvV > 0 ? (power / pvV) : 0;

const store = context.get("mppts") || {};
store[msg.pvMeta.unitId] = {
    instance: msg.pvMeta.unitId,
    name: msg.pvMeta.name,
    voltage: pvV.toFixed(2),
    current: pvI.toFixed(1),
    power: power,
    yield: yieldToday.toFixed(2)
};
context.set("mppts", store);

const keys = Object.keys(store);
if (keys.length < msg.pvMeta.count) return null;

const strings = [];
let total = 0;
for (const k of keys.sort((a, b) => a - b)) {
    strings.push(store[k]);
    total += store[k].power;
}

const pvStrings = {
    total: total,
    strings: strings,
    updated: new Date().toISOString()
};

global.set("pvStrings", pvStrings);
node.status({ fill: "green", shape: "dot", text: `${strings.length} MPPT · ${total} W` });

if (debug) node.warn("pvStrings (Modbus): " + JSON.stringify(pvStrings));

msg.payload = pvStrings;
return msg;

