//
// File Name        : N/A
// Title            : Battery W counter (obnoveno ze zálohy 28-06-2025)
// Author           : http://www.prochazka.zde.cz -> hacesoft 2025
// Created          : 04-02-2025, 18:19
// Revised          : 10-07-2026
// Version          : 2.0 (Dashboard 2.0 - bez GUI výstupů, jen akumulace)
// Target Platform  : Node-RED
//
// This code is distributed under the GNU Public License
// Všechny informace jsou zahrnuty pod GPL licenci, pokud není explicitně uveden jiný typ licence.
// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2026 hacesoft.
//*****************************************************************************

const debug = false;  // Debugging flag

// Globální funkce
const nConvertSignetUnsignet = global.get('nConvertSignetUnsignet');
if (!nConvertSignetUnsignet) {
    node.error('Globální funkce nebyly nalezeny. <- Battery W counter');
    return null;
}

// Načtení aktuálních hodnot
let nBuffer = 0;
let nBattery_input_Wh = global.get("nBattery_input_Wh") || 0;
let nBattery_output_Wh = global.get("nBattery_output_Wh") || 0;
let nBatteryALL_input_Wh = global.get("nBatteryALL_input_Wh") || 0;
let nBatteryALL_output_Wh = global.get("nBatteryALL_output_Wh") || 0;
let nBattery_Power = global.get("nBattery_Power") || 0;   // Battery Power (System) 842 ve W

let nSignet_Battery_Power = nConvertSignetUnsignet(nBattery_Power);

// Mrtvé pásmo - šum kolem nuly nepočítat (idle spotřeba BMS/měniče není cyklus baterie)
const DEADBAND_W = 15;

if (nSignet_Battery_Power > DEADBAND_W) {              // nabíjení baterie
    nBuffer = nSignet_Battery_Power / 3600;
    nBattery_input_Wh += nBuffer;
    nBatteryALL_input_Wh += nBuffer;
} else if (nSignet_Battery_Power < -DEADBAND_W) {      // vybíjení baterie
    nBuffer = Math.abs(nSignet_Battery_Power) / 3600;
    nBattery_output_Wh += nBuffer;
    nBatteryALL_output_Wh += nBuffer;
}
// v pásmu ±15 W se nic nepřičítá

// Uložení do globálních proměnných
global.set("nBattery_input_Wh", nBattery_input_Wh);
global.set("nBattery_output_Wh", nBattery_output_Wh);
global.set("nBatteryALL_input_Wh", nBatteryALL_input_Wh);
global.set("nBatteryALL_output_Wh", nBatteryALL_output_Wh);

// Debugovací výstup
if (debug) {
    node.warn(`Baterie IN: ${nBattery_input_Wh.toFixed(2)} Wh, OUT: ${nBattery_output_Wh.toFixed(2)} Wh (ALL IN: ${nBatteryALL_input_Wh.toFixed(2)}, ALL OUT: ${nBatteryALL_output_Wh.toFixed(2)})`);
}

msg.payload = {
    nBattery_input_Wh: nBattery_input_Wh.toFixed(2),
    nBattery_output_Wh: nBattery_output_Wh.toFixed(2),
    nBatteryALL_input_Wh: nBatteryALL_input_Wh.toFixed(2),
    nBatteryALL_output_Wh: nBatteryALL_output_Wh.toFixed(2)
};

return msg;

