// Debugging flag
const debug = false;  // Nastavte na true pro zapnutí debug zpráv

//definice globalních funkci
const fSetConfigProperty = global.get('setConfigProperty');
const convertUnixTimestamp = global.get('convertUnixTimestamp');

// Povolené klíče konfigurace (ochrana proti nechtěnému zápisu)
const arrBoolKeys = [
    "nGridConsumptionEnable",
    "nControl_Mode_ESS_AC_Grid",
    "nEnergyThresholdInjector",
    "switchSpotGridCharging",
    "nNonBatteryPriorityMode",
    "switchDelayCharging",
    "nSOCDeltaBeforeExport_Switch",
    "nDynamicSOC_Reserve",
    "nMorningPeakBatterySales",
    "nPredictionThreshold",
    "nEveningPeakBatterySales",
    "sGridChargingSwitch"
];
const arrNumKeys = [
    "nSetGridValue",
    "nSOCDeltaBeforeExport",
    "nMorningSOC_sales",
    "sPredictionThresholdKW",
    "nEveningSOC_sales",
    "nGridChargingSOC"
];
const arrTimeKeys = ["tStartBattery", "tStopBattery"];

// Klíče zrcadlené i do global kontextu (zachování chování Dashboard 1.0)
const arrMirrorGlobals = [
    "nControl_Mode_ESS_AC_Grid",
    "nNonBatteryPriorityMode",
    "switchSpotGridCharging"
];

// "HH:MM" -> ms od půlnoci (stejný formát, jaký posílal time input v Dashboard 1.0)
function hhmmToMs(s) {
    const m = /^(\d{1,2}):(\d{2})/.exec(String(s || ""));
    if (!m) return 0;
    return (Number(m[1]) * 3600000) + (Number(m[2]) * 60000);
}

switch (msg.topic) {

    case "init": {
        // widget se právě načetl -> trigger pro ESS :: Config_Build
        node.status({ fill: "blue", shape: "dot", text: "init " + new Date().toLocaleTimeString() });
        return msg;
    }

    case "set": {
        const sKey = msg.payload.key;
        const value = msg.payload.value;

        if (arrBoolKeys.includes(sKey)) {
            const bValue = !!value;
            fSetConfigProperty(sKey, bValue);
            if (arrMirrorGlobals.includes(sKey)) {
                global.set(sKey, bValue);
            }
            node.status({ fill: "green", shape: "dot", text: sKey + " = " + bValue });

        } else if (arrTimeKeys.includes(sKey)) {
            // stejná pipeline jako v Dashboard 1.0: ms od půlnoci -> convertUnixTimestamp -> config
            let stored = hhmmToMs(value);
            if (typeof convertUnixTimestamp === "function") {
                stored = convertUnixTimestamp(stored, debug);
            }
            fSetConfigProperty(sKey, stored);
            node.status({ fill: "green", shape: "dot", text: sKey + " = " + stored });

        } else if (arrNumKeys.includes(sKey)) {
            fSetConfigProperty(sKey, Number(value) || 0);
            node.status({ fill: "green", shape: "dot", text: sKey + " = " + value });

        } else {
            node.status({ fill: "red", shape: "ring", text: "neznámý klíč: " + sKey });
            if (debug) { node.warn("Neznámý klíč: " + sKey); }
        }

        if (debug) { node.warn("SET " + sKey + ": " + value); }
        return null;
    }
}

return null;

