//*****************************************************************************

// Debugging flag
const debug = false;  // Nastavte na true pro zapnutí debug zpráv

//definice globalních funkci
const fGetConfigProperty = global.get('getConfigProperty');

// Pomocna funkce: prevod ulozeneho casu na "HH:MM" pro <input type="time">
// (zvlada number = ms od pulnoci, number = unix timestamp i string "HH:MM[:SS]")
function toHHMM(v) {
    if (v === null || v === undefined || v === 0) return "00:00";
    if (typeof v === "number") {
        if (v > 86400000) { // unix timestamp v ms
            const d = new Date(v);
            return String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
        }
        const h = Math.floor(v / 3600000);
        const m = Math.floor((v % 3600000) / 60000);
        return String(h).padStart(2, "0") + ":" + String(m).padStart(2, "0");
    }
    const mt = /(\d{1,2}):(\d{2})/.exec(String(v));
    return mt ? (mt[1].padStart(2, "0") + ":" + mt[2]) : "00:00";
}

const bControlMode = !!fGetConfigProperty("nControl_Mode_ESS_AC_Grid");
const bNonBattery  = !!fGetConfigProperty("nNonBatteryPriorityMode");
