const bGridCharging = !!fGetConfigProperty("sGridChargingSwitch");

// Zrcadleni do globalu - zachovani chovani SET GUI1/2/3 z Dashboard 1.0
global.set("nControl_Mode_ESS_AC_Grid", bControlMode);
global.set("nNonBatteryPriorityMode", bNonBattery);
