// Používání těchto stránek a produktů ke komerčním účelům lze jen se souhlasem autora.
// Všechna práva vyhrazena (c) 1997 - 2026 hacesoft.
//
//*****************************************************************************

// Debugging flag
const debug = false;  // Nastavte na true pro zapnutí debug zpráv

//definice globalních funkci
const fSetConfigProperty = global.get('setConfigProperty');
const fGetConfigProperty = global.get('getConfigProperty');

// Povolené klíče konfigurace (ochrana proti nechtěnému zápisu)
const arrAllowedKeys = [
    "nSunriseProductionOffset",
    "nHouseHourlyConsumption",
    "nSetPeak",
    "nMAX_Grid_Point",
    "nBalancingReserve",
    "nCharging_DurationGRID",
    "nAcceptable_Price_GRID"
];

// Výstupy: [1] modbus GET (flex-getter), [2] modbus SET (write), [3] zpět do widgetu
switch (msg.topic) {

    case "init": {
        // widget se právě načetl -> pošli mu konfiguraci
        const payload = {
            nSunriseProductionOffset: fGetConfigProperty("nSunriseProductionOffset") || 0,
            nHouseHourlyConsumption:  fGetConfigProperty("nHouseHourlyConsumption") || 0,
            nSetPeak:                 fGetConfigProperty("nSetPeak") || 0,
            nMAX_Grid_Point:          fGetConfigProperty("nMAX_Grid_Point") || 0,
            nBalancingReserve:        fGetConfigProperty("nBalancingReserve") || 0,
            nCharging_DurationGRID:   fGetConfigProperty("nCharging_DurationGRID") || 0,
            nAcceptable_Price_GRID:   fGetConfigProperty("nAcceptable_Price_GRID") || 0,
            nGridFeed:                Math.floor(global.get("nGET_Grid_Feed_2706") || 0)
        };
        node.status({ fill: "blue", shape: "dot", text: "init " + new Date().toLocaleTimeString() });
        return [null, null, { topic: "config", payload: payload }];
    }

    case "set": {
        // uložení jedné položky konfigurace
        const sKey = msg.payload.key;
        const sValue = msg.payload.value;

        if (sKey === "nGridFeed") {
            // hodnota Grid Feed In se drží mimo config strukturu (kompatibilita s Dashboard 1.0)
            global.set("nGET_Grid_Feed_2706x", sValue);
        } else if (arrAllowedKeys.includes(sKey)) {
            fSetConfigProperty(sKey, sValue);
        } else {
            node.status({ fill: "red", shape: "ring", text: "neznámý klíč: " + sKey });
            if (debug) { node.warn("Neznámý klíč: " + sKey); }
            return null;
        }

        node.status({ fill: "green", shape: "dot", text: sKey + " = " + sValue });
        if (debug) { node.warn("SET " + sKey + ": " + sValue); }
        return null;
    }

    case "getFeed": {
        // čtení registru 2706 přes modbus-flex-getter
        msg.payload = {
            value: 0,
            'fc': 4,
            'unitid': 100,
            'address': 2706,
            'quantity': 1
        };
        node.status({ fill: "yellow", shape: "dot", text: "GET 2706" });
        return [msg, null, null];
    }

    case "setFeed": {
        // zápis registru 2706 (SCALE 0.01 -> W / 100)
        const nValue = Number(msg.payload) || 0;
        global.set("nGET_Grid_Feed_2706x", nValue);              // kompatibilita s Dashboard 1.0
        msg.payload = Math.floor(nValue / 100);                  // com.victronenergy.settings / Maximum System Grid Feed In / 2706 / int16 / 0,01
        node.status({ fill: "yellow", shape: "dot", text: "SET 2706 = " + msg.payload });
        if (debug) { node.warn("SET Grid Feed 2706 (raw): " + msg.payload); }
        return [null, msg, null];
    }
}

return null;

