// Debugging flag
const debug = false;  // Nastavte na true pro zapnutí debug zpráv

// --- data z Config_6 (kapacita baterie / časy) ---
const nRequiredTimeEnd = global.get("requiredTimeEnd") || 0;
const nRequiredTimeOffsetEnd = global.get("requiredTimeOffsetEnd") || 0;
const tBatteryTimeEnd = global.get("batteryTimeEnd") || "00:00:00";
const tBatteryTimeOffsetEnd = global.get("batteryTimeOffsetEnd") || "00:00:00";

// --- data z Config_7 (morning/afternoon peak) ---
const morningPeak = global.get("morningPeak") || [];
const afternoonPeak = global.get("afternoonPeak") || [];

// Funkce pro formátování pole na krátký text
function formatPeakHours(peakArray) {
    if (Array.isArray(peakArray) && peakArray.length > 0) {
        const firstHour = peakArray[0];
        const lastHour = peakArray[peakArray.length - 1];
        return (peakArray.length === 1) ? `[${firstHour}h]` : `[${firstHour}h-${lastHour}h]`;
    }
    return "[Žádný]";
}

// --- data z Config_10 (SPOT GRID peak) ---
const arrBuffer = global.get("arrSPOT_GRIF_Peak") || [];
let spotGridPeak = "[Žádný SPOT peak]";
let spotColor = "#ffbb00";
if (Array.isArray(arrBuffer) && arrBuffer.length > 0) {
    const firstHour = arrBuffer[0];
    const lastHour = arrBuffer[arrBuffer.length - 1];
    if (arrBuffer.length === 1) {
        spotGridPeak = `[${firstHour}h]`;
    } else {
        spotGridPeak = `[${firstHour}h - ${lastHour}h]`;
        spotColor = "#4CAF50";
    }
}

msg.topic = "live";
msg.payload = {
    nRequiredTimeEnd: nRequiredTimeEnd.toFixed(2),
    nRequiredTimeOffsetEnd: nRequiredTimeOffsetEnd.toFixed(2),
    tBatteryTimeEnd,
    tBatteryTimeOffsetEnd,
    morningPeak: formatPeakHours(morningPeak),
    afternoonPeak: formatPeakHours(afternoonPeak),
    spotGridPeak,
    spotColor
};

// Debugging
if (debug) {
    node.warn("live payload: " + JSON.stringify(msg.payload));
}

return msg;

