//*****************************************************************************
// Real Data — cte vse primo z globalu a sklada strukturu pro ui-template
// (c) 1997 - 2026 hacesoft. GPL.
//*****************************************************************************

const AutoformatValue = global.get('AutoformatValue');
const nConvertSignetUnsignet = global.get('nConvertSignetUnsignet');
const scaleFactor = 10;

// ---- AC zatez ----
const phase1 = global.get('phase1') || 0;
const phase2 = global.get('phase2') || 0;
const phase3 = global.get('phase3') || 0;

const ac = {
    total: phase1 + phase2 + phase3,
    p1: phase1, p2: phase2, p3: phase3,
    t1: global.get('Temperature_L1') || 0,
    t2: global.get('Temperature_L2') || 0,
    t3: global.get('Temperature_L3') || 0,
    wh1: AutoformatValue(parseFloat(global.get('output_L1_Wh') || 0)),
    wh2: AutoformatValue(parseFloat(global.get('output_L2_Wh') || 0)),
    wh3: AutoformatValue(parseFloat(global.get('output_L3_Wh') || 0))
};

// ---- Sit ----
const grid1 = global.get('grid1') || 0;
const grid2 = global.get('grid2') || 0;
const grid3 = global.get('grid3') || 0;

const grid = {
    total: grid1 + grid2 + grid3,
    g1: grid1, g2: grid2, g3: grid3,
    in1: AutoformatValue(parseFloat(global.get('grid_input_L1_Wh') || 0)),
    out1: AutoformatValue(parseFloat(global.get('grid_output_L1_Wh') || 0)),
    in2: AutoformatValue(parseFloat(global.get('grid_input_L2_Wh') || 0)),
    out2: AutoformatValue(parseFloat(global.get('grid_output_L2_Wh') || 0)),
    in3: AutoformatValue(parseFloat(global.get('grid_input_L3_Wh') || 0)),
    out3: AutoformatValue(parseFloat(global.get('grid_output_L3_Wh') || 0))
};

// ---- Baterie ----
const bat = {};
if (nConvertSignetUnsignet) {
    let bPower = nConvertSignetUnsignet(global.get('nBattery_Power'));
    let bCurrent = nConvertSignetUnsignet(global.get('nBattery_Current'));
    let bVoltage = nConvertSignetUnsignet(global.get('nBattery_Voltage'));

    bat.powerLabel = bPower > 0 ? 'Nabíjení baterie' : (bPower < 0 ? 'Vybíjení baterie' : 'Baterie Idle');
    bat.currentLabel = bCurrent > 0 ? 'Nabíjecí proud baterie' : (bCurrent < 0 ? 'Vybíjecí proud baterie' : 'Baterie Idle');

    bat.soc = global.get('nBattery_State_Charge');
    bat.socLimit = (global.get('nESS_BatteryLife_SoC_limit') || 0) / scaleFactor;
    bat.power = bPower;
    bat.current = bCurrent / scaleFactor;
    bat.voltage = bVoltage / scaleFactor;

    const inAll = global.get('nBatteryALL_input_Wh') || 0;
    const outAll = global.get('nBatteryALL_output_Wh') || 0;

    // Účinnost počítej až od 100 Wh nabité energie, jinak nemá vypovídací hodnotu.
    // Clamp na 100 % — fyzikálně nemůže být vyšší (krátkodobě může out předběhnout in,
    // např. vybíjení energie nabité před resetem čítačů).
    const MIN_INPUT_WH = 100;
    if (inAll >= MIN_INPUT_WH) {
        bat.eff = Math.min((outAll / inAll) * 100, 100).toFixed(2);
    } else {
        bat.eff = '—';
    }

    bat.inWhSum = AutoformatValue(inAll);
    bat.outWhSum = AutoformatValue(outAll);
} else {
    node.error('Globální funkce nebyly nalezeny. <- RD Build');
}

// ---- FV stringy ----
const pvG = global.get("pvStrings") || {};
const pvs = {
    total: global.get('pvPower') || 0,   // real-time celkovka z Modbusu
    strings: pvG.strings || []           // per-string z VRM (5 min interval)
};

// ---- Solar ----
const solar = global.get('pvPower') || 0;

// ---- VRM live feed + forecast ----
const live = global.get('sAPI_live_feed') || {};
const fc = global.get('sAPI_forecast') || {};
const lt = live.totals || {};
const ft = fc.totals || {};

// ---- Slunce & pocasi ----
const sunG = global.get("sunData") || {};
const qa = sunG.quick_access || {};
const wx = global.get("weatherData") || {};

const sun = {
    sunrise: qa.sunrise || "—",
    sunset: qa.sunset || "—",
    dayLength: qa.day_length || "—",
    today: wx.today || "—",
    rainProb: wx.rainProbToday !== undefined ? wx.rainProbToday + " %" : "—",
    trend: wx.trend || "—"
};

const stats = {
    gridTo: lt.grid_history_to !== undefined ? parseFloat(lt.grid_history_to).toFixed(1) : '0.0',
    gridFrom: lt.grid_history_from !== undefined ? parseFloat(lt.grid_history_from).toFixed(1) : '0.0',
    consFc: ft.vrm_consumption_fc !== undefined ? (parseFloat(ft.vrm_consumption_fc) / 1000).toFixed(1) : '0.0',
    consTotal: lt.total_consumption !== undefined ? parseFloat(lt.total_consumption).toFixed(1) : '0.0',
    solarFc: ft.solar_yield_forecast !== undefined ? (parseFloat(ft.solar_yield_forecast) / 1000).toFixed(1) : '0.0',
    solarTotal: lt.total_solar_yield !== undefined ? parseFloat(lt.total_solar_yield).toFixed(1) : '0.0'
};

msg.payload = { ac, grid, bat, solar, stats, sun, pvs };
return msg;

