    node.warn(`Fáze 3 (Grid): Vstup: ${grid_input_L3_Wh.toFixed(2)} Wh, Výstup: ${grid_output_L3_Wh.toFixed(2)} Wh`);
    node.warn(`Fáze 1 (Výstup): Výstup: ${output_L1_Wh.toFixed(2)} Wh`);
    node.warn(`Fáze 2 (Výstup): Výstup: ${output_L2_Wh.toFixed(2)} Wh`);
    node.warn(`Fáze 3 (Výstup): Výstup: ${output_L3_Wh.toFixed(2)} Wh`);
