function finiteOrNull(v){
    const n=Number(v);
    return Number.isFinite(n)?n:null;
}

function localDateYmd(offsetDays=0){
    const d=new Date();
    d.setDate(d.getDate()+offsetDays);
    const y=d.getFullYear();
    const m=String(d.getMonth()+1).padStart(2,"0");
    const day=String(d.getDate()).padStart(2,"0");
    return `${y}-${m}-${day}`;
}

function buildSpotDay(raw,date){
    const arr=Array.isArray(raw)?raw:[];
    return {
        date,
        available:arr.length>0,
        prices:arr.map((v,hour)=>({
            hour,
            price:finiteOrNull(v)
        }))
    };
}

function buildForecastSeries(raw){
    const arr=Array.isArray(raw)?raw:[];
    return arr
        .filter(item=>Array.isArray(item)&&item.length>=2)
        .map(item=>{
            const ts=finiteOrNull(item[0]);
            const wh=finiteOrNull(item[1]);
            const timestampMs=ts===null?null:(ts<100000000000?ts*1000:ts);
            return {
                timestampMs,
                timestamp:timestampMs===null?null:new Date(timestampMs).toISOString(),
                energyKWh:wh===null?null:wh/1000
            };
        });
}

function buildVrmFallback(){
    const t=rawVrmLive.totals||{};
    if(!available(rawVrmLive) || !available(t)) return null;

    const inWh=finiteOrNull(global.get("nBatteryALL_input_Wh"));
    const outWh=finiteOrNull(global.get("nBatteryALL_output_Wh"));

    return {
        updatedAt:null,
        source:"Victron VRM live_feed + LINEA battery counters",
        today:{
            pvYieldKWh:finiteOrNull(t.total_solar_yield),
            consumptionKWh:finiteOrNull(t.total_consumption),
            gridImportKWh:finiteOrNull(t.grid_history_from),
            gridExportKWh:finiteOrNull(t.grid_history_to),
            batteryChargeKWh:inWh===null?null:inWh/1000,
            batteryDischargeKWh:outWh===null?null:outWh/1000
        }
    };
}

function tempGlobalName(name){
    return String(name||"")
        .replace(/Menic|Teplota/g,"Temperature")
        .replace(/\s+/g,"_");
}

function buildTemperatureFallback(){
    const keys=Object.keys(rawSensorMapping||{});
    if(keys.length===0) return null;

    const racks=[], inverters=[], other=[];
    keys.forEach(k=>{
        const cfg=rawSensorMapping[k]||{};
        const name=cfg.customName||`Sensor ${k}`;
        const val=finiteOrNull(global.get(tempGlobalName(name)));
        const item={name,temperatureC:val};

        if(/(menic|měnič|inverter)/i.test(name)) inverters.push(item);
        else if(/(rack|battery|baterie|baterka)/i.test(name)) racks.push(item);
        else other.push(item);
    });

    return {
        updatedAt:null,
        racks,
        inverters,
        other
    };
}

function buildSmokeFallback(){
    const cfg=(rawShellyCfg&&Array.isArray(rawShellyCfg.smoke))?rawShellyCfg.smoke:[];
    if(cfg.length===0) return [];

    const now=Date.now();
    return cfg.map(d=>{
        const s=rawSmokeBuffer[d.id]||null;
        const lastMs=s&&Number(s.last_seen)>0?Number(s.last_seen):null;
        return {
            name:d.name||null,
            alarm:s?s.alarm??null:null,
            ok:s?s.ok??null:null,
            batteryPct:s?s.bat_pct??null:null,
            batteryVoltageV:s?s.bat_v??null:null,
            rssiDbm:s?s.rssi??null:null,
            wakeupReason:s?s.wakeup??null:null,
            lastSeen:lastMs?new Date(lastMs).toISOString():null,
            ageSec:lastMs?Math.max(0,Math.floor((now-lastMs)/1000)):null
        };
    });
}

