if (msg.payload === 'saveOrder' && Array.isArray(msg.order)) {
    const shellyDevices = global.get('shellyDevices') || { switches: [] };
    const list = shellyDevices.switches || [];

    // poradove cislo podle topicu (mqtt_id + ':'/'#' + channel)
    const orderMap = {};
    msg.order.forEach((t, i) => { orderMap[t] = i; });

    const topicOf = (d) => {
        const ch = (d.channel !== undefined ? d.channel : 0);
        return d.mqtt_id + (d.kind === 'input' ? '#' : ':') + ch;
    };

    list.forEach(d => {
        const t = topicOf(d);
        if (orderMap[t] !== undefined) d.order = orderMap[t];
    });

    // seraď samotne pole switches podle order (aby to bylo konzistentni i jinde)
    list.sort((a, b) => {
        const oa = (a.order !== undefined ? a.order : 9999);
        const ob = (b.order !== undefined ? b.order : 9999);
        return oa - ob;
    });

    shellyDevices.switches = list;
    global.set('shellyDevices', shellyDevices);
    return null;
