//*****************************************************************************
// DAIKIN - načtení tokenů ze souboru
//
// Pouze načte a uloží tokeny do global contextu.
// REFRESH ZDE NESPouštíme.
// Po načtení odešleme pouze "tokensLoaded" do Daikin startup sync.
//*****************************************************************************

let tokens = {};

try {
    if (
        msg.payload &&
        typeof msg.payload === "string" &&
        msg.payload.trim()
    ) {
        tokens = JSON.parse(msg.payload);

    } else if (
        msg.payload &&
        typeof msg.payload === "object"
    ) {
        tokens = msg.payload;
    }

} catch (e) {
    node.warn(
        "Daikin: nelze parsovat tokens soubor: " +
        e.message
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "chyba tokens souboru"
    });

    return null;
}


// Uložení tokenů do global context
global.set("daikinTokens", tokens);


// Stav tokenů pro UI
global.set("daikinTokenState", {
    hasRefresh: !!tokens.refresh_token,
    accessExpires: tokens.access_expires || 0
});


if (tokens.refresh_token) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "refresh token načten"
    });

} else {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "refresh token chybí"
    });
}


// Pouze oznámení startup synchronizaci.
// Ta sama rozhodne, zda už máme i Client ID + Secret.
return {
    topic: "daikinStartup",
    payload: "tokensLoaded"
};

//*****************************************************************************
// DAIKIN TOKEN MANAGER
//
// - používá access token, pokud je ještě platný
// - jinak obnoví token přes refresh_token
// - forceRefresh vynutí obnovu
// - chrání proti SOUČASNÉMU spuštění dvou refresh requestů
//*****************************************************************************

const config = global.get("config") || {};
const d = config.daikinConfig || {};
const tokens = global.get("daikinTokens") || {};

const clientId = String(d.clientId || "").trim();
const clientSecret = String(d.clientSecret || "").trim();
const refreshToken = String(tokens.refresh_token || "").trim();


// -----------------------------------------------------------------------------
// KONTROLA KONFIGURACE
// -----------------------------------------------------------------------------

if (!clientId || !clientSecret) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "čekám na Client ID/Secret"
    });

    global.set("daikinTokenState", {
        hasRefresh: !!refreshToken,
        accessExpires: tokens.access_expires || 0
    });

    return null;
}


if (!refreshToken) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "čekám na refresh token"
    });

    global.set("daikinTokenState", {
        hasRefresh: false
    });

    return null;
}


// -----------------------------------------------------------------------------
// JE ACCESS TOKEN JEŠTĚ PLATNÝ?
// -----------------------------------------------------------------------------

const force = (msg.payload === "forceRefresh");

const valid =
    tokens.access_token &&
    tokens.access_expires &&
    (tokens.access_expires - Date.now() > 5 * 60000);


if (valid && !force) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "access OK"
    });

    // Výstup 2 -> GET devices
    return [
        null,
        { daikin_access: tokens.access_token }
    ];
}


// -----------------------------------------------------------------------------
// OCHRANA PROTI PARALELNÍMU REFRESHI
// -----------------------------------------------------------------------------
//
// Daikin refresh token může rotovat.
// Dva současné requesty se stejným refresh tokenem jsou proto nežádoucí.
//

const now = Date.now();
const refreshStarted = global.get("daikinRefreshInFlight") || 0;

// Pokud refresh běží méně než 60 s, druhý nespouštěj.
if (refreshStarted && (now - refreshStarted < 60000)) {
    node.status({
        fill: "blue",
        shape: "ring",
        text: "refresh již probíhá"
    });

    return null;
}

// Starý lock po 60 s považujeme za neplatný.
global.set("daikinRefreshInFlight", now);


// -----------------------------------------------------------------------------
// REFRESH REQUEST
// -----------------------------------------------------------------------------

node.status({
    fill: "blue",
    shape: "ring",
    text: "obnovuji access token..."
});

msg.method = "POST";
msg.url = "https://idp.onecta.daikineurope.com/v1/oidc/token";

msg.headers = {
    "Content-Type": "application/x-www-form-urlencoded"
};

msg.payload =
    "grant_type=refresh_token" +
    "&client_id=" + encodeURIComponent(clientId) +
    "&client_secret=" + encodeURIComponent(clientSecret) +
    "&refresh_token=" + encodeURIComponent(refreshToken);


// Výstup 1 -> POST token endpoint
return [msg, null];

//*****************************************************************************
// DAIKIN - zpracování odpovědi token endpointu
//*****************************************************************************

const base = global.get("sValid_Patch") || "";
const r = msg.payload;
const tokens = global.get("daikinTokens") || {};


// Refresh request je dokončen - vždy uvolnit lock.
global.set("daikinRefreshInFlight", 0);


// -----------------------------------------------------------------------------
// CHYBA
// -----------------------------------------------------------------------------

if (!r || !r.access_token) {
    const err =
        (r && (r.error_description || r.error))
            ? (r.error_description || r.error)
            : ("HTTP " + (msg.statusCode || "?"));

    node.warn(
        "Daikin token refresh selhal: " +
        err
    );

    node.status({
        fill: "red",
        shape: "dot",
        text: "refresh selhal: " + err
    });

    global.set("daikinTokenState", {
        hasRefresh: !!tokens.refresh_token,
        accessExpires: tokens.access_expires || 0,
        lastError: err
    });

    return [
        null,
        {
            saveResult:
                "❌ Token se nepodařilo vygenerovat: " +
                err
        }
    ];
}


// -----------------------------------------------------------------------------
// ÚSPĚCH
// -----------------------------------------------------------------------------

tokens.access_token = r.access_token;

tokens.access_expires =
    Date.now() +
    (r.expires_in ? r.expires_in * 1000 : 10800000);


// Daikin může refresh token rotovat.
// Pokud přišel nový, MUSÍME uložit nový.
if (r.refresh_token) {
    tokens.refresh_token = r.refresh_token;
}


global.set("daikinTokens", tokens);

global.set("daikinTokenState", {
    hasRefresh: true,
    accessExpires: tokens.access_expires
});


const expTime =
    new Date(tokens.access_expires)
        .toLocaleTimeString("cs-CZ");


node.status({
    fill: "green",
    shape: "dot",
    text: "token OK do " + expTime
});


// -----------------------------------------------------------------------------
// ZÁPIS TOKENŮ DO SOUBORU
// -----------------------------------------------------------------------------

const writeMsg = {
    payload: JSON.stringify(tokens, null, 2),
    filename: base + "daikin_tokens.json",
    daikin_access: tokens.access_token
};


const uiMsg = {
    saveResult:
        "✅ Údaje OK, access token platí do " +
